create view bultos_pendientes as
  select id, deposito_id, peso_kg, estado from bultos where estado = 'pendiente'
  with check option;
update bultos_pendientes set estado = 'entregado' where id = 1;

-- como dueño de las tablas
create view bultos_publicos as
  select id, deposito_id, peso_kg, estado, creado from bultos;
grant select on bultos_publicos to ana;

-- como ana
select count(*) from bultos;
select costo from bultos_publicos limit 1;

-- como dueño
alter table bultos enable row level security;
create policy solo_mi_deposito on bultos for select to ana
  using (deposito_id = current_setting('app.deposito')::int);

-- como ana
set app.deposito = '2';
select count(*) as filas_por_la_vista from bultos_publicos;

-- como dueño
alter view bultos_publicos set (security_invoker = true);
grant select (id, deposito_id, peso_kg, estado, creado) on bultos to ana;

-- como ana
set app.deposito = '2';
select count(*) as filas_por_la_vista from bultos_publicos;
select costo from bultos limit 1;

create view sin_devueltos as select id, estado from bultos where estado <> 'devuelto';
-- Mala crea lab.curioso(text), que hace `raise notice` y devuelve true, con cost 0.0000001
select id, estado from sin_devueltos where id between 36 and 40 and lab.curioso(estado);

