create materialized view reporte_mensual as
select deposito_id, date_trunc('month', creado)::date as mes,
       count(*) as bultos, round(sum(costo)) as costo_total
from bultos group by 1, 2;
create unique index on reporte_mensual (deposito_id, mes);

