create function costo_envio_pl(peso numeric, zona text) returns numeric
language plpgsql immutable as $$
begin
  if peso <= 0 then raise exception 'peso invalido: %', peso; end if;
  return round(peso * 35 + case zona when 'Sur' then 10 when 'Norte' then 25 else 40 end, 2);
end $$;

