create function primero_de_mes(f date) returns date language plpgsql as $$
begin return make_date(extract(year from f)::int, extract(month from f)::int, 1); end $$;
create index on bultos (primero_de_mes(creado));

create function sorteo_mal() returns int language plpgsql immutable as $$ begin return (random() * 1000)::int; end $$;
create function sorteo_bien() returns int language plpgsql volatile as $$ begin return (random() * 1000)::int; end $$;
select sorteo_mal() as inmutable_mentirosa, sorteo_bien() as volatil from generate_series(1, 4);

create policy ver_ingenuo on miembros for select to ana
  using (grupo in (select grupo from miembros where usuario = current_setting('app.yo')::int));
-- como ana:
select * from miembros;

create function soy_miembro(g int) returns boolean language sql security definer stable
set search_path = public as $$
  select exists (select 1 from public.miembros where grupo = g and usuario = current_setting('app.yo')::int)
$$;
create policy ver_con_funcion on miembros for select to ana using (soy_miembro(grupo));
-- como ana, siendo el usuario 11:
select * from miembros order by usuario;

-- dueño
create table vip (cliente int primary key);
insert into vip values (1), (2), (3);
create function es_vip(c int) returns boolean language sql security definer as $$
  select exists (select 1 from vip where cliente = c) $$;
grant execute on function es_vip(int) to public;

-- Mala
select es_vip(99) as antes;
create temp table vip (cliente int);
insert into vip values (99);
grant select on vip to public;
select es_vip(99) as con_tabla_temporal;

-- dueño: con search_path = public pero la tabla sin esquema
create or replace function es_vip(c int) returns boolean language sql security definer
set search_path = public as $$ select exists (select 1 from vip where cliente = c) $$;
-- Mala repite su tabla temporal y llama a la función:
select es_vip(99);

-- dueño: tabla con esquema
create or replace function es_vip(c int) returns boolean language sql security definer
set search_path = public as $$ select exists (select 1 from public.vip where cliente = c) $$;
-- Mala, lo mismo:
select es_vip(99);
